import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  if (config.scenePosition) {
    const pos = config.scenePosition;
    group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
    if (pos.rotationXYZ) {
      const [rx, ry, rz] = pos.rotationXYZ;
      group.rotation.order = 'XYZ';
      group.rotation.set(rx, ry, rz);
    }
    if (pos.scaleXYZ) {
      const [sx, sy, sz] = pos.scaleXYZ;
      group.scale.set(sx, sy, sz);
    }
  }

  if (config.imageUrl) {
    const texture = ctx.textureLoader.load(config.imageUrl);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;

    const aspect = 512 / 320;
    const geometry = new THREE.PlaneGeometry(aspect, 1);
    const material = new THREE.MeshBasicMaterial({
      map: texture,
      side: THREE.DoubleSide,
      toneMapped: false,
    });

    const mesh = new THREE.Mesh(geometry, material);
    group.add(mesh);
  }

  if (config.textContent && ctx.fontAtlas) {
    const text = typeof config.textContent === 'string'
      ? config.textContent
      : String(config.textContent);

    const textMesh = ctx.fontAtlas.createText(text, {
      fontSize: 0.34,
      color: 0x16161d,
      anchor: 'center',
      lineHeight: 1.2,
      maxWidth: 3,
    });

    if (textMesh) {
      textMesh.position.z = 0.1;
      group.add(textMesh);
    }
  }

  if (config.cinematicPrimitives?.length > 0 && ctx.primitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    group.traverse((child) => {
      if (child instanceof THREE.Mesh) {
        child.geometry?.dispose();
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach(mat => {
          mat?.map?.dispose();
          mat?.dispose();
        });
      }
    });
    gsap.killTweensOf(group);
  };

  return group;
}
